def countAllVowelsExactK(s, k):
    idx = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}

    def at_least(m):
        cnt = [0] * 5
        have = 0
        cons = 0
        left = 0
        total = 0
        for ch in s:
            j = idx.get(ch)
            if j is None:
                cons += 1
            else:
                if cnt[j] == 0:
                    have += 1
                cnt[j] += 1
            while have == 5 and cons >= m:
                d = idx.get(s[left])
                if d is None:
                    cons -= 1
                else:
                    cnt[d] -= 1
                    if cnt[d] == 0:
                        have -= 1
                left += 1
            total += left
        return total

    return at_least(k) - at_least(k + 1)
